import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import test from "node:test";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
// The bootstrap schema used to live inline in src/lib/setup/migration.ts
// as MIGRATION_NAMES / INITIAL_SCHEMA_SQL. It now lives in the migration
// bundle (generated by `npm run db:bundle`, gitignored), applied by
// src/lib/migrations/service.ts. These tests read the bundle instead.
const bundle = JSON.parse(
	readFileSync(join(root, "src/lib/migrations/bundle.json"), "utf8"),
);
const migrations = bundle.migrations;
const statements = migrations.flatMap((migration) => migration.statements);
const sql = statements.join(";\n");

test("bootstrap records migrations represented in the current schema so later deploys do not re-apply them", () => {
	const names = migrations.map((migration) => migration.name);
	for (const name of [
		"0013_add_license_settings.sql",
		"0021_add_mailbox_signature.sql",
		"0022_add_mailbox_auto_reply.sql",
		"0027_add_domain_sending_intent.sql",
		"0029_add_spam_protection.sql",
	]) {
		assert.ok(names.includes(name), `bundle is missing ${name}`);
	}
});

test("fresh bootstrap schema accepts the current Drizzle mailbox and license inserts", () => {
	for (const name of [
		"mailboxes",
		"license_settings",
		"auto_reply_deliveries",
		"spam_token_stats",
		"spam_reputation",
		"spam_feedback",
		"domains",
	]) {
		assert.match(
			sql,
			new RegExp(`CREATE TABLE \`?${name}\`? \\(`),
			`${name} CREATE TABLE not found`,
		);
	}
	assert.match(sql, /spam_protection_enabled/);

	// Apply every bundled statement to a fresh in-memory DB, then check the
	// columns added by later ALTER migrations (signature / auto-reply on
	// mailboxes, sending_requested on domains) and run the same inserts the
	// old inline-schema test ran. Statements are passed as JSON because
	// three FTS trigger bodies contain inner semicolons, so splitting the
	// joined SQL on ";" would break them.
	const py = `
import json, sqlite3, sys
stmts = json.load(sys.stdin)
db = sqlite3.connect(":memory:")
for s in stmts:
    db.execute(s)
def cols(table):
    return {row[1] for row in db.execute(f"PRAGMA table_info({table})")}
mb = cols("mailboxes")
for c in ["signature", "auto_reply_enabled", "auto_reply_subject", "auto_reply_body"]:
    assert c in mb, f"mailboxes missing column {c}"
assert "sending_requested" in cols("domains"), "domains missing sending_requested"
db.execute("INSERT INTO users (id,email,password_hash,name,created_at) VALUES ('u','a@b.c','x','n',1)")
db.execute("INSERT INTO domains (id,user_id,hostname,zone_id,created_at) VALUES ('d','u','ex.com','z',1)")
db.execute("""
INSERT INTO mailboxes (
  id, user_id, domain_id, local_part, display_name,
  signature, auto_reply_enabled, auto_reply_subject, auto_reply_body, created_at
) VALUES ('m','u','d','admin','admin','sig',0,'Out of office','',1)
""")
db.execute("INSERT INTO license_settings (id, instance_id, updated_at) VALUES ('default','inst',1)")
db.execute("INSERT INTO auto_reply_deliveries (id, mailbox_id, recipient, sent_at) VALUES ('ar','m','x@y.z',1)")
print("ok")
`;
	const result = spawnSync("python3", ["-c", py], {
		input: JSON.stringify(statements),
		encoding: "utf8",
	});
	assert.equal(result.status, 0, result.stderr + result.stdout);
	assert.match(result.stdout, /^ok$/m);
});
